{
  "correction_rules": [
    "Adjust forecasts downward when sentiment is negative or near-zero, as models tend to overestimate prices in stable or bearish sentiment.",
    "Apply a lag correction: if true outcome is significantly lower than forecast, reduce next-period forecast by 5-10% to account for mean reversion.",
    "Cap forecast spikes above 75% of recent 7-day high to prevent overshoot after sharp price increases.",
    "If forecast is consistently higher than true outcome over 3+ consecutive days, apply a downward bias correction of 3-5% per day.",
    "For sentiment history with negative values, reduce forecast volatility by 20% to reflect subdued market participation."
  ]
}
